#!/usr/bin/env bash
# homebrew-cask.sh <version> <dmg-sha256> <notarized:true|false> [repo]: prints Casks/dromon.rb
# for the Homebrew tap (release.yml's homebrew job writes it to fatihdogmus/homebrew-tap).
#
# While the app is not notarized, the cask strips macOS's quarantine flag from Dromon.app after
# install, so it opens without Gatekeeper's "Apple could not verify" block. Homebrew dropped
# --no-quarantine and allows this only outside its own taps; the cask says so in its caveats.
# Once the DMG is notarized (notarized=true) the postflight and caveats are left out.
# shellcheck source-path=SCRIPTDIR source=lib.sh
. "$(dirname "$0")/lib.sh"

[ $# -ge 3 ] || die "usage: homebrew-cask.sh <version> <dmg-sha256> <notarized:true|false> [repo]"
version=$1 sha=$2 notarized=$3 repo=${4:-fatihdogmus/dromon}
[[ $version =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || die "Not a release version: $version"
[[ $sha =~ ^[0-9a-f]{64}$ ]] || die "Not a SHA-256: $sha"
case $notarized in true | false) ;; *) die "notarized must be true or false, not $notarized" ;; esac

cat <<EOF
# Generated by https://github.com/$repo/blob/main/.github/release/homebrew-cask.sh
# for each published release; edits here are overwritten.
cask "dromon" do
  version "$version"
  sha256 "$sha"

  url "https://github.com/$repo/releases/download/#{version}/Dromon-#{version}-macos-arm64.dmg"
  name "Dromon"
  desc "Small, fast SFTP file browser"
  homepage "https://github.com/$repo"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on arch: :arm64
  depends_on macos: ">= :sonoma"

  app "Dromon.app"
EOF

if [ "$notarized" = false ]; then
  cat <<'EOF'

  # Dromon is not notarized yet (ad-hoc signed); without this, macOS refuses to open it.
  postflight do
    system_command "/usr/bin/xattr",
                   args: ["-dr", "com.apple.quarantine", "#{appdir}/Dromon.app"]
  end
EOF
fi

cat <<'EOF'

  uninstall quit: "dev.dromon.Dromon"

  zap trash: "~/Library/Saved Application State/dev.dromon.Dromon.savedState"
EOF

if [ "$notarized" = false ]; then
  cat <<'EOF'

  caveats <<~TEXT
    Dromon is not notarized by Apple yet. This cask removed the quarantine flag from
    #{appdir}/Dromon.app so macOS opens it; the DMG's SHA-256 above was checked against the
    release's build attestation when this cask was written.
  TEXT
EOF
fi

echo "end"
